<script setup lang="ts">import {Link,useForm} from '@inertiajs/vue3';import type {Patient} from '@/types';const props=defineProps<{patient?:Patient}>();const form=useForm({document_type:props.patient?.document_type??'',document_number:props.patient?.document_number??'',first_name:props.patient?.first_name??'',last_name:props.patient?.last_name??'',birth_date:props.patient?.birth_date?.slice(0,10)??'',age:props.patient?.age??null as number|null,sex:props.patient?.sex??'',email:props.patient?.email??'',phone:props.patient?.phone??'',address:props.patient?.address??''});const submit=()=>props.patient?form.put(route('admin.patients.update',props.patient.id)):form.post(route('admin.patients.store'));</script>
<template><form class="panel form-panel" @submit.prevent="submit"><div class="form-grid"><div class="field"><label for="first-name">Nombres</label><input id="first-name" v-model="form.first_name" required maxlength="255"><span class="field-error">{{ form.errors.first_name }}</span></div><div class="field"><label for="last-name">Apellidos</label><input id="last-name" v-model="form.last_name" required maxlength="255"><span class="field-error">{{ form.errors.last_name }}</span></div><div class="field"><label for="document-type">Tipo de documento</label><input id="document-type" v-model="form.document_type" maxlength="30"><span class="field-error">{{ form.errors.document_type }}</span></div><div class="field"><label for="document-number">Número de documento</label><input id="document-number" v-model="form.document_number" maxlength="100"><span class="field-error">{{ form.errors.document_number }}</span></div><div class="field"><label for="birth-date">Fecha de nacimiento</label><input id="birth-date" v-model="form.birth_date" type="date"><span class="field-error">{{ form.errors.birth_date }}</span></div><div class="field"><label for="age">Edad <i>si no hay fecha</i></label><input id="age" v-model.number="form.age" type="number" min="0" max="130"><span class="field-error">{{ form.errors.age }}</span></div><div class="field"><label for="sex">Sexo</label><input id="sex" v-model="form.sex" maxlength="30"><span class="field-error">{{ form.errors.sex }}</span></div><div class="field"><label for="email">Correo</label><input id="email" v-model="form.email" type="email" maxlength="255"><span class="field-error">{{ form.errors.email }}</span></div><div class="field"><label for="phone">Teléfono</label><input id="phone" v-model="form.phone" maxlength="40"><span class="field-error">{{ form.errors.phone }}</span></div><div class="field field--wide"><label for="address">Dirección</label><textarea id="address" v-model="form.address" maxlength="1000" rows="3"></textarea><span class="field-error">{{ form.errors.address }}</span></div></div><div class="form-actions"><Link class="button button--outline-small" :href="route('admin.patients.index')">Cancelar</Link><button class="button button--admin" :disabled="form.processing">{{ form.processing?'Guardando...':'Guardar paciente' }}</button></div></form></template>
